import java.util.*;

public class Main {
    public static void main(String[] args) {
        // BOM：只声明版本，不引入依赖
        Map<String, String> bom = new LinkedHashMap<>();
        bom.put("spring-core", "6.1.1");
        bom.put("spring-web", "6.1.1");
        bom.put("spring-tx", "6.1.1");
        bom.put("jackson-databind", "2.15.3");

        // 模块自己的 dependencyManagement：显式声明优先于导入的 BOM
        Map<String, String> ownMgmt = new LinkedHashMap<>();
        ownMgmt.put("jackson-databind", "2.16.0");

        // 模块 dependencies：不写版本，靠管理段推导
        String[][] deps = {
                {"spring-core", ""},
                {"spring-web", ""},
                {"jackson-databind", ""},
                {"guava", "33.0.0-jre"},
        };

        System.out.println("=== imported BOM (spring-boot-dependencies) ===");
        bom.forEach((k, v) -> System.out.println("  " + k + " : " + v));
        System.out.println();
        System.out.println("=== project's own dependencyManagement (wins over BOM) ===");
        ownMgmt.forEach((k, v) -> System.out.println("  " + k + " : " + v));

        System.out.println();
        System.out.println("=== effective versions of declared dependencies ===");
        int fromBom = 0, fromOwn = 0, explicit = 0;
        Set<String> used = new LinkedHashSet<>();
        for (String[] d : deps) {
            String art = d[0], ver, src;
            used.add(art);
            if (!d[1].isEmpty()) {
                ver = d[1]; src = "explicit"; explicit++;
            } else if (ownMgmt.containsKey(art)) {
                ver = ownMgmt.get(art); src = "own management"; fromOwn++;
            } else if (bom.containsKey(art)) {
                ver = bom.get(art); src = "BOM"; fromBom++;
            } else {
                ver = "UNRESOLVED"; src = "missing";
            }
            System.out.printf("  %-18s %-14s <- %s%n", art, ver, src);
        }

        // 正确口径：BOM 里存在、但模块从未声明依赖它的条目
        List<String> unused = new ArrayList<>();
        for (String k : bom.keySet()) if (!used.contains(k)) unused.add(k);

        System.out.println();
        System.out.println("=== summary ===");
        System.out.println("  resolved from BOM          : " + fromBom);
        System.out.println("  resolved from own mgmt     : " + fromOwn);
        System.out.println("  explicitly declared        : " + explicit);
        System.out.println("  managed in BOM but NOT a dependency of this module : " + unused);
        System.out.println("  => management section only supplies a version; it pulls nothing in");
    }
}
